function esc(s){if(!s)return'-';var d=document.createElement('div');d.textContent=s;return d.innerHTML;}
function fmt(n){if(!n&&n!==0)return'-';return Number(n).toLocaleString('zh-CN');}
function fmtTime(ts){if(!ts)return'-';var d=new Date(ts);return d.toLocaleString('zh-CN');}
function badgePub(m){return m&&m.matched!==false?'<span class="badge badge-published">已发布</span>':'<span class="badge badge-review">审核中</span>';}

