function renderComments(){var container=document.getElementById('commentContainer');if(!container||!DATA_COMMENT){container&&((container.innerHTML='<div class="empty">暂无评论数据</div>'));return;}
var comments=(DATA_COMMENT.comments)||[];if(!comments.length){container.innerHTML='<div class="empty">今日暂无评论数据</div>';return;}
var html='';for(var k=0;k<comments.length;k++){var c=comments[k];var isNeg=/差评|不好|垃圾|坑|骗|失望|后悔/i.test(c.content||'');
var replyHtml=c.reply?'<div class="comment-reply"><div class="reply-label">运营回复</div><div class="reply-text">'+esc(c.reply)+'</div></div>':'<div style="font-size:12px;color:var(--muted);margin-top:6px;">尚未回复</div>';
html+='<div class="comment-card"><div class="comment-meta"><span class="author">'+esc(c.author||'匿名用户')+'</span><span class="time">'+fmtTime(c.time)+'</span><span class="badge" style="'+(isNeg?'background:rgba(239,68,68,.15);color:var(--red);':'background:rgba(16,185,129,.15);color:var(--green);')+'">'+(isNeg?'负面':'正面')+'</span></div>';
html+='<div class="comment-body">'+esc(c.content)+'</div>'+replyHtml+'</div>';}
container.innerHTML=html;}

